package com.jadhavr.erp.fee.entity;
import com.jadhavr.erp.admission.entity.AdmissionForm; import com.jadhavr.erp.college.entity.College; import com.jadhavr.erp.common.entity.BaseAuditEntity; import com.jadhavr.erp.department.entity.Department; import com.jadhavr.erp.fee.enums.FeeAccountStatus; import com.jadhavr.erp.student.entity.StudentProfile; import com.jadhavr.erp.user.entity.User; import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="student_fee_accounts",uniqueConstraints=@UniqueConstraint(name="uk_fee_account_admission",columnNames="admission_form_id")) public class StudentFeeAccount extends BaseAuditEntity {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="student_id",nullable=false) private StudentProfile student; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="student_user_id",nullable=false) private User studentUser; @OneToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="admission_form_id",nullable=false) private AdmissionForm admissionForm; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="college_id",nullable=false) private College college; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="department_id",nullable=false) private Department department; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="fee_structure_id",nullable=false) private FeeStructure feeStructure;
 @Column(nullable=false,length=20) private String academicYear; @Column(nullable=false,precision=12,scale=2) private BigDecimal totalFee; @Column(nullable=false,precision=12,scale=2) private BigDecimal paidAmount=BigDecimal.ZERO; @Column(nullable=false,precision=12,scale=2) private BigDecimal remainingAmount; @Column(nullable=false,precision=12,scale=2) private BigDecimal discountAmount=BigDecimal.ZERO; @Column(nullable=false,precision=12,scale=2) private BigDecimal minimumAmountForAdmission; @Enumerated(EnumType.STRING) @Column(nullable=false,length=25) private FeeAccountStatus status=FeeAccountStatus.PENDING;
 public Long getId(){return id;} public void setId(Long v){id=v;} public StudentProfile getStudent(){return student;} public void setStudent(StudentProfile v){student=v;} public User getStudentUser(){return studentUser;} public void setStudentUser(User v){studentUser=v;} public AdmissionForm getAdmissionForm(){return admissionForm;} public void setAdmissionForm(AdmissionForm v){admissionForm=v;} public College getCollege(){return college;} public void setCollege(College v){college=v;} public Department getDepartment(){return department;} public void setDepartment(Department v){department=v;} public FeeStructure getFeeStructure(){return feeStructure;} public void setFeeStructure(FeeStructure v){feeStructure=v;} public String getAcademicYear(){return academicYear;} public void setAcademicYear(String v){academicYear=v;} public BigDecimal getTotalFee(){return totalFee;} public void setTotalFee(BigDecimal v){totalFee=v;} public BigDecimal getPaidAmount(){return paidAmount;} public void setPaidAmount(BigDecimal v){paidAmount=v;} public BigDecimal getRemainingAmount(){return remainingAmount;} public void setRemainingAmount(BigDecimal v){remainingAmount=v;} public BigDecimal getDiscountAmount(){return discountAmount;} public void setDiscountAmount(BigDecimal v){discountAmount=v;} public BigDecimal getMinimumAmountForAdmission(){return minimumAmountForAdmission;} public void setMinimumAmountForAdmission(BigDecimal v){minimumAmountForAdmission=v;} public FeeAccountStatus getStatus(){return status;} public void setStatus(FeeAccountStatus v){status=v;}
}
